{
    int m, n;
    printf("Enter number of rows and columns : ");
    scanf("%d%d", &m, &n);
    int **A = NULL, **sparserow = NULL, **sparsecol = NULL;
    A = readmatrix(A, m, n);
    sparserow = createsparserow(A, m, n);
    sparsecol = createsparsecol(A, m, n);
    displayrowmajor(sparserow);
    displaycolmajor(sparsecol);
