#include "shell.h"


int history_dis(__attribute__((unused))char **c, __attribute__((unused))int s)
{
    char *filename = ".simple_shell_history";
    FILE *fp;
    char *line = NULL;
    size_t len = 0;
    int counter = 0;
    char *er;

    fp = fopen(filename, "r");
    if (fp == NULL)
    {
        return (-1);
    }
    while ((getline(&line, &len, fp)) != -1)
    {
        counter++;
        er = _itoa(counter);
        PRINTER(er);
        free(er);
        PRINTER(" ");
        PRINTER(line);

    }
    if (line)
        free(line);
    fclose(fp);
    return (0);
}

int print_echo(char **cmd)
{
    pid_t pid;
    int status;

    pid = fork();
    if (pid == 0)
    {
    if (execve("/bin/echo", cmd, environ) == -1)
    {
        return (-1);
    }
        exit(EXIT_FAILURE);
    }
    else if (pid < 0)
    {
        return (-1);
    }
    else
    {
        do {
            waitpid(pid, &status, WUNTRACED);
        } while (!WIFEXITED(status) && !WIFSIGNALED(status));
    }
    return (1);
}
