        printf("Data: %s\n" , buf);
        printf("----------------------------------------\n\n");


        if (sendto(socket_udp, buf, recv_len, 0, (struct sockaddr*) &si_client, slen) == -1)
        {
            error("sendto()");
        }

        bzero(buf, BUFLEN);
    }

    close(socket_udp);
    return 0;
