void    ft_pgcd(int a, int b)
{
    int     cdn;
    int     i;

    i = 1;
    cdn = 0;
    while (i < a && i < b)
    {
        if (a % i == 0 && b % i == 0)
            cdn = i;
        i++;
    }
    ft_putnbr(cdn);
}

