void display(int array[MAX], int length)
{
    int i = 0;
    for(i=0; i<length; i++)
        printf("%d\t", array[i]);

    printf("\n");
}


int linear_search(int array[MAX], int length, int key)
{
    int i, index = -1;
    int size = length;

    for(i=0; i<size; i++)
    {

        if(array[i] == key)
        {
            index = i;
            break;
        }
        else
            continue;
    }

    return index;
