int kmin(int arr[], int size, int k)
{
  int  temp = 0, count = 0, index = 0;

  while(count <= k)
  { 
    int min = arr[count], index = count;
    for(int i = count; i < size; i++)
    {
      if(min > arr[i])
      {
        min = arr[i];
    index = i;
      }
    }
    if(count != index)
    {
      temp = arr[index];

      arr[index] = arr[count];

      arr[count] = temp;

    }
    count++;

  }
  return (count-1);
}
