   return itemCount == 0;
}

bool isFull() {
   return itemCount == MAX;
}



int enqueue(int data) {

   if(!isFull()) {
        rear=rear+1;
        queue[rear]=data;

   itemCount++;}
}

int dequeue() {
   int data;
