void displayMat(float **mat,int r,int c)
    {
    int i,j;
    for(i=0;i<r;i++)
        {
        for(j=0;j<c;j++)
        printf("%f ",mat[i][j]);
        printf("\n");
        }
    }
float deterMat(float **mat,int r,int c)
    {
    int i,j,k;
    float det,ratio;
    for(i = 0; i < r; i++)
        {
            for(j = 0; j < c; j++)
                {
                    if(j>i)
                        {
                        ratio = mat[j][i]/mat[i][i];
                        for(k = 0; k < r; k++)
                                mat[j][k] -= ratio * mat[i][k];
                        }
                }
            }
        det = 1; 
        for(i = 0; i < r; i++)
            det *= mat[i][i];
        return det;
        }


