static char *dirname(char *path)
{
  char *lastSeparator = strrchr(path, '\\');
  if (lastSeparator != NULL) 
  {
    *lastSeparator = '\0';
    return path;
  }
  else
  {
    *path = '\0';
  }
  return path;
}
