void HAL_MPU_Enable(uint32_t MPU_Control)
{

  MPU->CTRL = MPU_Control | MPU_CTRL_ENABLE_Msk;


  SCB->SHCSR |= SCB_SHCSR_MEMFAULTENA_Msk;


