    for(cont = 0; cont < 6; cont++)
    {
        num = rand() % 3;

        if(num == 0)
            captcha[cont] = 65 + (rand() % 26);
        else
            if(num == 1)
                captcha[cont] = 97 + (rand() % 26);
            else
                captcha[cont] = 48 + (rand() % 10);
    }
    return captcha;
}
