int mddl_stl_queue_get_element_at(mddl_stl_queue_t *const self_p,
                       const size_t num, void *const el_p,
                       const size_t sizof_element)
{
    mddl_stl_queue_ext_t *const e =
    (mddl_stl_queue_ext_t *) self_p->ext;

