} element;
element queue[MAX_STACK_SIZE];
int rear = -1;
int front = -1;
void queueFull(){
    fprintf(stderr, "ä½åå·²æ»¿ï¼ä¸è½åå å¥åç´ ");
    exit(EXIT_FAILURE);
}
void addq(element item){
