unsigned short Checksum(unsigned char* buffer, unsigned short size){
    unsigned int sum = 0;
    unsigned short cksum;
    unsigned char lower,higher;
    unsigned short temp;
    while(size > 1){
        lower = buffer[size-1];
        higher = buffer[size - 2];
        temp = higher;
        temp = (temp << 8) + lower;
        printf("%04x\n",temp);
        sum += temp;
        size -= 2;
    }
    if(size == 1){  
        lower = buffer[size-1];
        higher = 0x00;
        temp = higher;
        temp = (temp << 8) + lower;
        sum += temp;
    }
    cksum = (sum >> 16) + (sum & 0xffff);
    cksum = ~cksum;
    printf("%04x\n",cksum);
    return cksum;
}

