typedef struct
{
    int c[20];
    int front;
    int rear;
}queue;
void enqueueright(queue *q,int n)
{
    if (q->rear==20)
        printf("Side Full\n");
    else
        q->c[(q->rear)++]=n;
}
void enqueueleft(queue *q,int n)
{
    if (q->front==0)
        printf("Side Full\n");
    else
        q->c[--(q->front)]=n;
}
int dequeueleft(queue *q)
{
    if (q->front==q->rear)
    {
        printf("Queue Empty");
        return -1;
    }
    else
        return q->c[(q->front)++];
}
int dequeueright(queue *q)
{
    if (q->front==q->rear)
    {
        printf("Queue Empty");
        return -1;
    }
    else
        return q->c[--(q->rear)];
}
void display(queue *q)
{
    int i;
    for (i=q->front;i<q->rear;i++)
        printf("%d\t",q->c[i]);
    printf("\n");
}
