int* bsearch(int* first, int size, int x)
{
    int* last = first + size - 1;

    while(first <= last)
    {
        int *mid = first + (last - first)/2;

        if(*mid == x)
            return mid;

        else if(*mid > x)
            last = mid - 1;

        else if(*mid < x)
            first = mid + 1;
    }

    return NULL;
}

