void scambia(int v[], int dim, int i, int j){

    if(dim > 0)
    {
        if((i >= 0) && (i <= dim) && (j >= 0) && (j <= dim))
        {
            int tmp = v[i];
            v[i] = v[j];
            v[j] = tmp;
        }
    }
}

